#!/usr/bin/env node
// Generates supabase/functions/_shared/brand-origins.generated.ts FROM the one brand contract
// (docs/brand/brand-contract.v1.json). Nobody edits the generated file; test/brand-origins.test.mjs
// regenerates it in memory and fails on any difference, so the contract and the allowlist cannot drift.
//
// "SUPPORTED" IS NOT "ACTIVE". The browser-origin allowlist contains the origin of EVERY identity in the
// contract (HomeSignal and Jody) so the backend answers a Jody-origin page correctly the day one exists.
// That changes no behaviour today: no page is served from the Jody origin, and authorization never depends
// on the origin (admin-gate.ts: identify() runs the same token + allow-list checks for every caller).
//
//   node scripts/gen-brand-origins.mjs           write the file
//   node scripts/gen-brand-origins.mjs --check   exit 1 if the committed file differs
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';
import { validateContract, contractHash } from '../test/lib/brand-contract.mjs';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
export const CONTRACT_FILE = 'docs/brand/brand-contract.v1.json';   // the contract's version lives INSIDE the file; the file name is stable
export const OUT_FILE = 'supabase/functions/_shared/brand-origins.generated.ts';

/**
 * Where a reply to a no-reply sender should go, per identity. A sending domain being VERIFIED at the mail provider says nothing about a person
 * reading replies; a customer who answers `noreply@jodytracks.com` otherwise writes to nobody. HomeSignal's value is null: its watch email has never
 * carried a Reply-To and stays byte-identical. Jody's is the mailbox that exists (contact@jodytracks.com, Infomaniak) and is read by a person.
 * Changing a mailbox is a reviewed edit HERE, in the one place the brand's outbound identity is derived.
 */
export const REPLY_TO_BY_IDENTITY = { homesignal: null, jody: 'contact@jodytracks.com' };

/** The pre-contract allowlist also carried the www host of HomeSignal. Kept explicitly, never inferred. */
export const LEGACY_EXTRA_ORIGINS = ['https://www.homesignal.net'];

export function render(contract) {
  validateContract(contract);
  const cur = contract.identities[contract.current_identity].origin;
  const fut = contract.identities[contract.future_identity].origin;
  const origins = [cur, ...LEGACY_EXTRA_ORIGINS, fut];
  const ident = contract.identities[contract.current_identity];
  if (!(contract.current_identity in REPLY_TO_BY_IDENTITY)) throw new Error('no reply-to decision recorded for identity ' + contract.current_identity);
  const replyTo = REPLY_TO_BY_IDENTITY[contract.current_identity];
  if (new Set(origins).size !== origins.length) throw new Error('duplicate origin in derived allowlist');
  return `// GENERATED by scripts/gen-brand-origins.mjs from ${CONTRACT_FILE}. DO NOT EDIT.
// Regenerate: node scripts/gen-brand-origins.mjs   Verified by: test/brand-origins.test.mjs
//
// Browser origins the backend recognises (supported, NOT activated): the origin of every identity in the
// brand contract, plus the legacy www host. Order: current identity, its legacy host(s), future identity.
export const BRAND_CONTRACT_SHA256 = '${contractHash(contract)}';
export const BROWSER_ORIGINS: readonly string[] = [
${origins.map((o) => `  '${o}',`).join('\n')}
];
// What the site PUBLISHES as (the contract's current identity). The links and sender the backend EMITS are built from these, so
// moving the brand is the contract change and one redeploy, never an edit to five files. While the contract is v1 these are
// exactly the strings that used to be written out in those files (pinned by test/brand-origins.test.mjs section 6).
export const PUBLIC_ORIGIN = '${cur}';
export const PUBLIC_HOST = '${new URL(cur).host}';
export const PUBLIC_NAME = '${ident.display_name}';
// Where a reply to a no-reply sender goes (null = the sender carries no Reply-To, as HomeSignal's never has). See REPLY_TO_BY_IDENTITY in the generator.
export const PUBLIC_REPLY_TO: string | null = ${replyTo === null ? 'null' : `'${replyTo}'`};
`;
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const want = render(JSON.parse(readFileSync(join(root, CONTRACT_FILE), 'utf8')));
  if (process.argv.includes('--check')) {
    let have = ''; try { have = readFileSync(join(root, OUT_FILE), 'utf8'); } catch { /* missing */ }
    if (have !== want) { console.error(`${OUT_FILE} is out of date; run: node scripts/gen-brand-origins.mjs`); process.exit(1); }
    console.log('brand origins: up to date');
  } else { writeFileSync(join(root, OUT_FILE), want); console.log(`wrote ${OUT_FILE}`); }
}
